"use client";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Star, User, MapPin, Calendar } from "lucide-react";
import Image from "next/image";
import { useRouter } from "next/navigation";

export interface CardItem {
  id: string;
  subject?: string;
  title?: string;
  description?: string;
  proof?: string;
  price?: number | string;
  class?: string;
  Class?: string;
  method?: string;
  mode?: string;
  address?: string | null;
  schedule?: string;
  schedules?: Array<{ day: string; startTime: string; endTime: string }>;
  rating?: number;
  reviewCount?: number;
  tutor?: {
    id?: string | number;
    name?: string;
    avatar?: string;
    rating?: number;
    reviewCount?: number;
  };
  [key: string]: any;
}

export function CardImage({ data }: { data: CardItem }) {
  const router = useRouter();

  const handleSeeMore = () => {
    router.push(`/seemore/${data.id}`);
  };

  const handleRegister = () => {
    router.push(`/register/${data.id}`);
  };

  const tutorName = data.tutor?.name || data.tutorName || "Gia sư";
  const rating = Number(data.rating ?? data.tutor?.rating ?? 5.0).toFixed(1);
  const reviewCount = data.reviewCount ?? data.tutor?.reviewCount ?? 0;
  const grade = data.class || data.Class || "Lớp 12";
  const mode = data.method || data.mode || "Offline";
  const proofImg =
    data.proof && data.proof.startsWith("http")
      ? data.proof
      : "https://bizweb.dktcdn.net/100/255/283/themes/588445/assets/cate_2_2.jpg?1786698433736";

  const priceText =
    typeof data.price === "number"
      ? `${data.price.toLocaleString("vi-VN")} đ/tháng`
      : data.price
      ? `${data.price} đ/tháng`
      : "Thỏa thuận";

  const scheduleText =
    Array.isArray(data.schedules) && data.schedules.length > 0
      ? data.schedules.map((s) => `${s.day} (${s.startTime})`).join(", ")
      : data.schedule || "Lịch học linh hoạt";

  return (
    <Card className="group relative mx-auto w-full max-w-sm overflow-hidden rounded-lg border border-slate-200 bg-white p-0 shadow-sm transition-all duration-150 hover:shadow-md">
      {/* Thumbnail to rộng rãi hơn h-52 */}
      <div className="relative h-52 w-full overflow-hidden bg-slate-100">
        <Image
          src={proofImg}
          alt={data.subject || "Khóa học"}
          fill
          sizes="(max-width: 768px) 100vw, 33vw"
          className="object-cover transition-transform duration-200 group-hover:scale-105"
        />
        <div className="absolute top-2 right-2 flex gap-1.5">
          <span className="rounded bg-black/75 px-2.5 py-0.5 text-xs font-semibold text-white">
            {mode}
          </span>
          <span className="rounded bg-blue-600 px-2.5 py-0.5 text-xs font-semibold text-white">
            {grade}
          </span>
        </div>
      </div>

      {/* Thông tin đầy đủ, chữ to rõ, spacing khít */}
      <CardHeader className="p-3.5 pb-2 space-y-1.5">
        {/* Môn học + Giá tiền */}
        <div className="flex items-center justify-between gap-2">
          <CardTitle className="text-lg font-bold text-slate-900 line-clamp-1">
            {data.subject || data.title || "Khóa học"}
          </CardTitle>
          <span className="shrink-0 text-base font-extrabold text-emerald-600">
            {priceText}
          </span>
        </div>

        {/* Tên Gia sư + Đánh giá sao */}
        <div className="flex items-center justify-between text-sm pt-0.5 border-t border-slate-100">
          <div className="flex items-center gap-1.5 font-semibold text-slate-800 truncate">
            <User className="size-4 text-slate-500 shrink-0" />
            <span className="truncate">Gia sư: {tutorName}</span>
          </div>

          <div className="flex items-center gap-1 font-bold text-amber-500 shrink-0">
            <Star className="size-4 fill-amber-400 text-amber-400" />
            <span>{rating}</span>
            <span className="text-xs font-normal text-slate-400">({reviewCount})</span>
          </div>
        </div>

        {/* Mô tả 2 dòng chữ rõ ràng */}
        <p className="line-clamp-2 text-sm text-slate-600 leading-snug">
          {data.description || "Khóa học chất lượng cao cùng gia sư tận tâm."}
        </p>

        {/* Địa chỉ & Lịch học đầy đủ */}
        <div className="space-y-1 text-xs text-slate-600 pt-0.5">
          <div className="flex items-center gap-1.5 truncate">
            <MapPin className="size-3.5 text-slate-400 shrink-0" />
            <span className="truncate">Địa chỉ: {data.address || "Đà Nẵng"}</span>
          </div>
          <div className="flex items-center gap-1.5 truncate">
            <Calendar className="size-3.5 text-slate-400 shrink-0" />
            <span className="truncate">Lịch học: {scheduleText}</span>
          </div>
        </div>
      </CardHeader>

      {/* Nút hành động */}
      <CardFooter className="flex items-center gap-2 p-3.5 pt-1">
        <Button
          variant="outline"
          size="sm"
          className="h-8 flex-1 rounded-md text-sm font-semibold text-slate-700 hover:bg-slate-100"
          onClick={handleSeeMore}
        >
          Chi tiết
        </Button>
        <Button
          size="sm"
          className="h-8 flex-1 rounded-md bg-zinc-800 text-sm font-semibold text-white hover:bg-zinc-700"
          onClick={handleRegister}
        >
          Đăng ký
        </Button>
      </CardFooter>
    </Card>
  );
}
